+// duplicateTaskMember walks a syntactically valid JSON value, keeping names
+// local to their containing object.
+func duplicateTaskMember(raw json.RawMessage) (string, bool) {
+	dec := json.NewDecoder(bytes.NewReader(raw))
+	dec.UseNumber()
+	var scan func() (string, bool)
+	scan = func() (string, bool) {
+		token, err := dec.Token()
+		if err != nil {
+			return "", false
+		}
+		switch token {
+		case json.Delim('{'):
+			seen := make(map[string]struct{})
+			for dec.More() {
+				token, err := dec.Token()
+				if err != nil {
+					return "", false
+				}
+				key := token.(string)
+				if _, found := seen[key]; found {
+					return key, true
+				}
+				seen[key] = struct{}{}
+				if foundKey, found := scan(); found {
+					return foundKey, true
+				}
+			}
+			_, _ = dec.Token()
+		case json.Delim('['):
+			for dec.More() {
+				if key, found := scan(); found {
+					return key, true
+				}
+			}
+			_, _ = dec.Token()
+		}
+		return "", false
+	}
+	return scan()
 }

